<?php
use Solitude\Theme;
use Solitude\View;
$doc=new DOMDocument('1.0','UTF-8');$old=libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8"><div id="sl-overlay-root">'.file_get_contents(__DIR__.'/../resources/overlays.html').'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($old);$xpath=new DOMXPath($doc);
$set=function(DOMNode $node,string $html)use($doc){$temp=new DOMDocument('1.0','UTF-8');$old=libxml_use_internal_errors(true);$temp->loadHTML('<?xml encoding="UTF-8"><div id="fragment">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($old);while($node->firstChild)$node->removeChild($node->firstChild);$root=$temp->getElementById('fragment');foreach(iterator_to_array($root->childNodes) as $child)$node->appendChild($doc->importNode($child,true));};
$has=fn($class)=>'//*[contains(concat(" ",normalize-space(@class)," ")," '.$class.' ")]';
$posts=Theme::publicPosts();$tags=View::taxonomy($posts);$categories=View::taxonomy($posts,'categories');
foreach($xpath->query($has('card-tag-cloud')) as $node){$limit=$xpath->query('ancestor::*[@id="console"]',$node)->length?20:(int)Theme::get('aside.tags.limit',20);$html='';foreach(array_slice($tags,0,$limit) as $tag)$html.='<a href="'.Theme::e($tag['permalink']).'" class="'.(in_array($tag['name'],Theme::get('aside.tags.highlight_list',[]),true)?'highlight':'').'">'.Theme::e($tag['name']).'<sup>'.$tag['count'].'</sup></a>';$set($node,$html);}
$months=[];foreach($posts as $p){$month=date('Y-m',$p->created);$months[$month]=($months[$month]??0)+1;}$archive='';foreach(array_slice($months,0,5,true) as $month=>$count)$archive.='<li class="item"><a href="'.Theme::e(Theme::url('archives/')).'"><span class="date">'.$month.'</span><div class="count-group"><span class="count">'.$count.'</span><span class="unit">'.Theme::e(Theme::t('postUnit')).'</span></div></a></li>';$archive.='<li class="item"><a href="'.Theme::e(Theme::url('archives/')).'"><span class="date">'.Theme::e(Theme::t('allPosts')).'</span><div class="count-group"><span class="count">'.count($posts).'</span><span class="unit">'.Theme::e(Theme::t('postUnit')).'</span></div></a></li>';
foreach($xpath->query($has('card-archive-list')) as $node)$set($node,$archive);
ob_start();View::menu(View::menus());$menu=ob_get_clean();foreach($xpath->query($has('menus_items')) as $node)$set($node,$menu);
foreach($xpath->query($has('back-menu-list-groups')) as $node){$html='';foreach(Theme::get('nav.group',[]) as $group=>$links){$html.='<div class="back-menu-list-group"><div class="back-menu-list-title">'.Theme::e($group).'</div><div class="back-menu-list">';foreach($links as $link)$html.='<a class="back-menu-item" href="'.Theme::e(Theme::url($link['url']??'#')).'"><span class="back-menu-item-text">'.Theme::e($link['name']??'').'</span></a>';$html.='</div></div>';}$set($node,$html);}
ob_start();View::siteInfo($posts);$info=ob_get_clean();foreach($xpath->query($has('webinfo')) as $node)$set($node,$info);
$counts=[count($posts),count($categories),count($tags)];foreach($xpath->query('//*[@id="sidebar-menus"]//*[contains(concat(" ",normalize-space(@class)," ")," length-num ")]') as $index=>$node)if(isset($counts[$index]))$set($node,(string)$counts[$index]);
$remove=function($selector)use($xpath){foreach(iterator_to_array($xpath->query($selector)) as $node)$node->parentNode?->removeChild($node);};
if(!Theme::get('console.enable'))$remove('//*[@id="console"]');
if(!Theme::get('console.card.tags'))$remove('//*[@id="console"]//*[contains(concat(" ",normalize-space(@class)," ")," tags ")]');
if(!Theme::get('console.card.archive'))$remove('//*[@id="console"]//*[contains(concat(" ",normalize-space(@class)," ")," history ")]');
if(!Theme::get('rightside.enable'))$remove('//*[@id="rightside"]');
if(!Theme::get('right_menu.enable'))$remove('//*[@id="rightMenu" or @id="rightmenu-mask"]');
if(!Theme::get('capsule.enable'))$remove('//*[@id="menu-music-toggle" or @id="menu-music-back" or @id="menu-music-forward" or @id="menu-music-copyMusicName"]');
if(!Theme::get('search.enable'))$remove('//*[@id="menu-search"]');
$shortcuts='';$labels=['toggleKeyboard'=>'keyboardDisable','showConsole'=>'keyboardConsole','musicToggle'=>'keyboardMusic','toggleTheme'=>'keyboardThemeDark','openSearch'=>'keyboardSearch','randomPost'=>'keyboardRandomPost'];
foreach(Theme::get('keyboard.list',[]) as $index=>$item)$shortcuts.='<div class="keyboardItem" role="listitem" data-shortcut-index="'.$index.'" data-shortcut-action="'.Theme::e($item['action']??'').'" data-shortcut-custom-label="'.(!empty($item['name'])?'true':'false').'" data-theme-light-label="'.Theme::e(Theme::t('keyboardThemeLight')).'" data-theme-dark-label="'.Theme::e(Theme::t('keyboardThemeDark')).'"><div class="keyGroup"><kbd class="key">'.(($item['modifier']??'')==='mod'?'⌘/Ctrl':'Shift').'</kbd><kbd class="key">'.Theme::e($item['key']??'').'</kbd></div><div class="keyContent"><span class="content">'.Theme::e($item['name']??Theme::t($labels[$item['action']??'']??($item['action']??''))).'</span></div></div>';
foreach($xpath->query($has('keyboardList')) as $node)$set($node,$shortcuts);
foreach($xpath->query($has('rightMenuOther')) as $node){$custom='';foreach(Theme::get('right_menu.custom_list',[]) as $item)$custom.='<button class="rightMenu-item '.Theme::e($item['class']??'').'" id="'.Theme::e($item['id']??'').'" type="button" data-solitude-action="runConfiguredAction" data-solitude-value="'.Theme::e($item['click']??'').'"><i class="solitude '.Theme::e($item['icon']??'fas fa-link').'"></i><span>'.Theme::e($item['name']??'').'</span></button>';$set($node,$custom.preg_replace('~^<div[^>]*>|</div>$~','',$doc->saveHTML($node)));}
if(Theme::get('translate.enable'))foreach($xpath->query('//*[@id="rightside-config-hide"]') as $node)$set($node,'<button id="translateLink" class="translate" type="button" aria-label="Translate">繁</button>'.preg_replace('~^<div[^>]*>|</div>$~','',$doc->saveHTML($node)));
foreach(['mode'=>'mode','aside'=>'aside'] as $key=>$class)if(!Theme::get('rightside.hide.'.$key))$remove('//*[@id="rightside-config-hide"]//*[contains(concat(" ",normalize-space(@class)," ")," '.$class.' ")]');
if(!Theme::get('rightside.hide.enable'))$remove('//*[@id="rightside-config"]');
if(Theme::get('comment.use'))foreach($xpath->query($has('rightMenuPlugin')) as $node){$existing=$doc->saveHTML($node);$set($node,'<button class="rightMenu-item" id="menu-commenttext" type="button" title="'.Theme::e(Theme::t('rightMenuComment')).'"><i class="solitude fas fa-comment-medical"></i><span>'.Theme::e(Theme::t('rightMenuComment')).'</span></button>'.preg_replace('~^<div[^>]*>|</div>$~','',$existing));}
if(Theme::get('comment.use')==='native'&&Theme::get('console.recentComment.enable'))foreach($xpath->query($has('console-card-group')) as $node){$existing=preg_replace('~^<div[^>]*>|</div>$~','',$doc->saveHTML($node));ob_start();View::commentCards(Theme::comments(6));$cards=ob_get_clean();$set($node,'<div class="console-card-group-left"><div class="console-card" id="card-newest-comments" data-solitude-action="hideConsole"><div class="card-content"><div class="author-content-item-tips">'.Theme::e(Theme::t('recentComments')).'</div><div class="author-content-item-title">'.Theme::e(Theme::t('comments')).(Theme::get('recent_comments.enable')?'<a class="recent-comment-more" href="'.Theme::e(Theme::url(Theme::get('recent_comments.page','recentcomments/'))).'" title="'.Theme::e(Theme::t('more')).'" aria-label="'.Theme::e(Theme::t('more')).'"><i class="solitude fas fa-circle-chevron-right" aria-hidden="true"></i></a>':'').'</div></div><div class="console_recentcomments" aria-live="polite" aria-busy="false">'.$cards.'</div></div></div>'.$existing);}
$en=json_decode(file_get_contents(__DIR__.'/../resources/i18n/en.json'),true);$reverse=array_flip(array_filter($en,'is_string'));
foreach($xpath->query('//text()[normalize-space(.)!=""]') as $node){$text=trim($node->nodeValue);if(isset($reverse[$text]))$node->nodeValue=Theme::t($reverse[$text]);}
foreach($xpath->query('//*[@aria-label or @title or @placeholder]') as $node)foreach(['aria-label','title','placeholder'] as $attribute){$text=$node->getAttribute($attribute);if(isset($reverse[$text]))$node->setAttribute($attribute,Theme::t($reverse[$text]));}
foreach($xpath->query('//*[@src]') as $node){$src=$node->getAttribute('src');if(str_starts_with($src,'/img/'))$node->setAttribute('src',Theme::media($src));}
if(!Theme::get('capsule.enable')){foreach($xpath->query('//*[@id="consoleMusic"]') as $node)$node->parentNode->removeChild($node);}if(!Theme::get('keyboard.enable')){foreach($xpath->query('//*[@id="keyboard-tips" or @id="consoleKeyboard"]') as $node)$node->parentNode->removeChild($node);}$root=$doc->getElementById('sl-overlay-root');foreach($root->childNodes as $node)echo $doc->saveHTML($node);
